begin;
create extension if not exists pgtap with schema extensions;
set search_path = public, extensions;
select no_plan();
insert into auth.users(id,email,email_confirmed_at) values
 ('10000000-0000-0000-0000-000000000001','profile-a@example.test',now()),
 ('10000000-0000-0000-0000-000000000002','profile-b@example.test',now()),
 ('10000000-0000-0000-0000-000000000003','profile-unverified@example.test',null);
set local role authenticated;
select set_config('request.jwt.claim.sub','10000000-0000-0000-0000-000000000001',true);
select lives_ok($$insert into public.user_account_profiles(display_name,bio) values (' Alex ',' Hello ')$$,'verified caller creates profile without community');
select is((select user_id from public.user_account_profiles),auth.uid(),'database supplies profile identity');
select lives_ok($$insert into public.user_account_profiles(display_name,bio) values ('Alex Updated','Updated') on conflict(user_id) do update set display_name=excluded.display_name,bio=excluded.bio$$,'own profile upsert succeeds');
select is((select display_name from public.user_account_profiles),'Alex Updated','updated name readable');
select is((select created_by from public.user_account_profiles),auth.uid(),'trusted creation actor');
select is((select updated_by from public.user_account_profiles),auth.uid(),'trusted update actor');
select ok((select updated_at >= created_at from public.user_account_profiles),'audit times populated');
select throws_ok($$update public.user_account_profiles set display_name=' '$$,'23514',null,'blank name rejected');
select throws_ok($$update public.user_account_profiles set display_name=repeat('a',81)$$,'23514',null,'long name rejected');
select throws_ok($$update public.user_account_profiles set bio=repeat('a',2001)$$,'23514',null,'long bio rejected');
select lives_ok($$update public.user_account_profiles set display_name=repeat('a',80),bio=repeat('a',2000)$$,'maximum lengths accepted');
select lives_ok($$update public.user_account_profiles set display_name=' Alex ',bio='  '$$,'blank bio accepted');
select is((select display_name from public.user_account_profiles),'Alex','database trims name');
select is((select bio from public.user_account_profiles),null::text,'database normalizes blank bio');
select throws_ok($$update public.user_account_profiles set created_by=null$$,'42501',null,'audit actor writes denied');
select throws_ok($$update public.user_account_profiles set updated_at=now()$$,'42501',null,'audit time writes denied');
select throws_ok($$update public.user_account_profiles set user_id='10000000-0000-0000-0000-000000000002'$$,'42501',null,'profile identity update denied');
select throws_ok($$insert into public.user_account_profiles(user_id,display_name) values ('10000000-0000-0000-0000-000000000002','Spoofed')$$,'42501',null,'caller cannot supply another profile identity');
select throws_ok($$delete from public.user_account_profiles$$,'42501',null,'profile deletion denied');
select ok((select user_is_discoverable and enable_matchmaking from public.user_accounts),'global defaults true');
select lives_ok($$update public.user_accounts set user_is_discoverable=false$$,'search opt-out');
select ok((select not user_is_discoverable and enable_matchmaking from public.user_accounts),'search preserves matching');
select lives_ok($$update public.user_accounts set enable_matchmaking=false$$,'matching opt-out');
select ok((select not user_is_discoverable and not enable_matchmaking from public.user_accounts),'matching preserves search');
select throws_ok($$update public.user_accounts set enable_matchmaking=null$$,'23502',null,'preferences non-null');
select set_config('test.profile_tenant',public.create_tenant('profile-test','Profile test','HN','UTC',null,null,true)::text,true);
select is((select show_global_profile from public.community_accounts),false,'community default false');
with edited as (update public.community_accounts set show_global_profile=true returning 1) select is((select count(*) from edited),1::bigint,'own community preference update');
select ok((select show_global_profile from public.community_accounts),'community independent of global preferences');
select lives_ok($$select public.join_community(current_setting('test.profile_tenant')::uuid)$$,'repeat join succeeds');
select ok((select show_global_profile from public.community_accounts),'repeat join preserves preferences');
select is((select count(*) from public.community_account_profiles),0::bigint,'global edits create no community profile');
select lives_ok($$insert into public.community_account_profiles(tenant_id,display_name,bio) values (current_setting('test.profile_tenant')::uuid,' Community ',' ') on conflict(tenant_id,user_id) do update set tenant_id=excluded.tenant_id,display_name=excluded.display_name,bio=excluded.bio$$,'community upsert succeeds');
select is((select display_name from public.community_account_profiles),'Community','community name normalized');
select throws_ok($$update public.community_accounts set standing='approved'$$,'42501',null,'preference grant cannot change standing');
select lives_ok($$select public.set_tenant_archived(current_setting('test.profile_tenant')::uuid,true)$$,'owner archives');
with edited as (update public.community_accounts set show_global_profile=false returning 1) select is((select count(*) from edited),0::bigint,'archived preference denied');
select throws_ok($$insert into public.community_account_profiles(tenant_id,display_name) values (current_setting('test.profile_tenant')::uuid,'Archived') on conflict(tenant_id,user_id) do update set display_name=excluded.display_name$$,'42501',null,'archived profile upsert denied');
select lives_ok($$update public.user_account_profiles set display_name='Still editable',bio='Global'$$,'global profile independent of archive');
select lives_ok($$update public.user_accounts set user_is_discoverable=true,enable_matchmaking=true$$,'global preferences independent of archive');
select lives_ok($$select public.set_tenant_archived(current_setting('test.profile_tenant')::uuid,false)$$,'owner restores');
select set_config('request.jwt.claim.sub','10000000-0000-0000-0000-000000000002',true);
select is((select count(*) from public.user_account_profiles),0::bigint,'other account cannot read profile');
with edited as (update public.user_account_profiles set display_name='Hijacked' returning 1) select is((select count(*) from edited),0::bigint,'other account cannot update profile');
with edited as (update public.community_accounts set show_global_profile=true returning 1) select is((select count(*) from edited),0::bigint,'unassociated preferences denied');
select ok((select user_is_discoverable and enable_matchmaking from public.user_accounts),'other account preferences untouched');
select set_config('request.jwt.claim.sub','10000000-0000-0000-0000-000000000003',true);
select throws_ok($$insert into public.user_account_profiles(display_name) values ('Unverified')$$,'42501',null,'unverified profile denied');
with edited as (update public.user_accounts set enable_matchmaking=false returning 1) select is((select count(*) from edited),0::bigint,'unverified preferences denied');
reset role;
update public.community_accounts set standing='suspended' where tenant_id=current_setting('test.profile_tenant')::uuid;
set local role authenticated;
select set_config('request.jwt.claim.sub','10000000-0000-0000-0000-000000000001',true);
with edited as (update public.community_accounts set show_global_profile=false returning 1)
 select is((select count(*) from edited),0::bigint,'suspended preference update denied even for owner participation');
select throws_ok($$insert into public.community_account_profiles(tenant_id,display_name) values (current_setting('test.profile_tenant')::uuid,'Suspended') on conflict(tenant_id,user_id) do update set display_name=excluded.display_name$$,'42501',null,'suspended profile upsert denied');
reset role;
update public.community_accounts set standing='removed' where tenant_id=current_setting('test.profile_tenant')::uuid;
set local role authenticated;
with edited as (update public.community_accounts set show_global_profile=false returning 1)
 select is((select count(*) from edited),0::bigint,'removed preference update denied');
select throws_ok($$insert into public.community_account_profiles(tenant_id,display_name) values (current_setting('test.profile_tenant')::uuid,'Removed') on conflict(tenant_id,user_id) do update set display_name=excluded.display_name$$,'42501',null,'removed profile upsert denied');
reset role;
update auth.users set banned_until=now()+interval '1 day' where id='10000000-0000-0000-0000-000000000001';
set local role authenticated;
select set_config('request.jwt.claim.sub','10000000-0000-0000-0000-000000000001',true);
with edited as (update public.user_account_profiles set display_name='Banned' returning 1) select is((select count(*) from edited),0::bigint,'banned profile denied');
with edited as (update public.community_accounts set show_global_profile=false returning 1) select is((select count(*) from edited),0::bigint,'banned community preferences denied');
set local role anon;
select throws_ok($$select * from public.user_account_profiles$$,'42501',null,'anonymous reads denied');
select throws_ok($$insert into public.user_account_profiles(display_name) values ('Anonymous')$$,'42501',null,'anonymous writes denied');
reset role;
select * from finish();
rollback;
